import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 2.2;
  const height = 1.375; // 512:320 aspect ratio preserved

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const texNode = texture(map, uv());

  // Subtle engineered gradient overlay using ink/surface tones, plus faint grain via uv-based noise-ish mix
  const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const surfaceColor = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 1.0);
  const gradientFactor = uv().y.clamp(0.0, 1.0);
  const gradient = mix(surfaceColor, inkColor, gradientFactor);

  const finalColor = mix(texNode, gradient, float(0.06));
  material.colorNode = finalColor;
  material.opacityNode = texNode.a;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-card-2-visual';

  const node = new THREE.Object3D();
  node.name = 'hub-pricing-card-2';
  node.add(mesh);

  node.position.set(3.2, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  node.userData.handlers = {};

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return node;
}
